/**
 * Returns Codebook documentation in Markdown and JSON.
 * 
 * @returns {object} { markdown: string, json: string, schema: Array }
 */
export function generateCodebook() {
  let md = '# PromptSketch Scientific Codebook\n\n';
  md += 'Generated automatically for research compliance, Open Science, and publication interoperability.\n\n';

  const levels = ['turn', 'session', 'longitudinal'];
  const levelTitles = {
    turn: 'Turn-Level Data Dictionary (`tidy_turns.csv`)',
    session: 'Session-Level Data Dictionary (`tidy_sessions.csv`)',
    longitudinal: 'Participant-Longitudinal Data Dictionary (`tidy_longitudinal.csv`)',
  };

  for (const lvl of levels) {
    md += `## ${levelTitles[lvl]}\n\n`;
    md += '| Variable | Type | Units | Operational Definition | Mathematical Formula | Allowable Range | Missing Code |\n';
    md += '|---|---|---|---|---|---|---|\n';

    const items = CODEBOOK_SCHEMA.filter(i => i.level === lvl);
    for (const item of items) {
      md += `| \`${item.var}\` | ${item.type} | ${item.unit} | ${item.definition} | \`${item.formula}\` | ${item.range} | \`${item.missing_value}\` |\n`;
    }
    md += '\n';
  }

  return {
    markdown: md,
    json: JSON.stringify(CODEBOOK_SCHEMA, null, 2),
    schema: CODEBOOK_SCHEMA,
  };
}
